INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(4101, 'Numbers 23:15', 'Numbers', 23, 15, '&nbsp;بلعام بلق ته ووئيل، ”د خپلې سوزېدونکې نذرانې سره ودرېږه او هلته به خُدائ پاک ما ته راڅرګند شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4102, 'Numbers 23:16', 'Numbers', 23, 16, '&nbsp;مالِک خُدائ بلعام ته راڅرګند شو، ورته يې فرمائيل چې دا خبرې به کوې او واپس يې بلق ته ولېږلو چې هغۀ ته دا پېغام ورسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4103, 'Numbers 23:17', 'Numbers', 23, 17, '&nbsp;نو هغه واپس لاړو او وې ليدل چې بلق د خپلې سوزېدونکې نذرانې سره ولاړ وو او د موآب مشران هم ورسره وُو. بلق ترې نه تپوس وکړو چې مالِک خُدائ څۀ فرمائيلى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4104, 'Numbers 23:18', 'Numbers', 23, 18, '&nbsp;او بلعام دا پېغام ورکړو، ”د صفور زويه بلقه پاڅه، او چې زۀ درته څۀ وايم هغه واوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4105, 'Numbers 23:19', 'Numbers', 23, 19, '&nbsp;خُدائ پاک د بنى آدم په شان نۀ دے، چې دروغ ووائى، هغه بنى آدم نۀ دے چې خپله فېصله بدله کړى. هغه چې کومه وعده وکړى، نو هغه پوره کوى، هغه چې څۀ وائى، نو هغه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4106, 'Numbers 23:20', 'Numbers', 23, 20, '&nbsp;ګوره، ما ته حُکم مِلاو شو چې د هغوئ دپاره برکت وغواړم، او چې کله خُدائ پاک برکت ورکړى، نو زۀ برکت واپس نۀ شم اخستلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4107, 'Numbers 23:21', 'Numbers', 23, 21, '&nbsp;زۀ د بنى اِسرائيلو په راتلونکى وخت پوهېږم په هغوئ به څۀ بدبختى يا مصيبت نۀ راځى. مالِک خُدائ د هغوئ خُدائ پاک د هغوئ مل دے، هغوئ اِعلان کوى چې هغه يې بادشاه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4108, 'Numbers 23:22', 'Numbers', 23, 22, '&nbsp;خُدائ پاک هغوئ د مِصر نه راويستلى دى، هغوئ د يو ځنګلى غوَيى په شان طاقت لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4109, 'Numbers 23:23', 'Numbers', 23, 23, '&nbsp;نۀ داسې جادو شته او نۀ داسې کوډې شته، چې د بنى اِسرائيلو په قوم باندې وشى. خلق به اوس د بنى اِسرائيلو په حقله ووائى، ګورئ، خُدائ پاک د هغوئ دپاره څۀ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4110, 'Numbers 23:24', 'Numbers', 23, 24, '&nbsp;د بنى اِسرائيلو قوم د يو تکړه ازمرى په شان دے، چې د شلولو او خرابولو نه مخکښې په آرام نۀ کښېنى، چې ترڅو يې د ښکار کړے شوى څيز وينه نۀ وى څښلې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4111, 'Numbers 23:25', 'Numbers', 23, 25, '&nbsp;بيا بلق بلعام ته ووئيل، ”تا په بنى اِسرائيلو باندې د لعنت وئيلو نه اِنکار کړے دے، خو ګوره چې برکت هم ورله ونۀ غواړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4112, 'Numbers 23:26', 'Numbers', 23, 26, '&nbsp;بلعام جواب ورکړو، ”ما تا ته نۀ دى وئيلى څۀ چې زۀ به هم هغه شان کوم څۀ چې مالِک خُدائ ما ته فرمائيلى دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4113, 'Numbers 23:27', 'Numbers', 23, 27, '&nbsp;بلق ووئيل، ”ما سره لاړ شه او زۀ به تا يو بل ځائ ته بوځم. کېدے شى چې د خُدائ پاک خوښه وى چې په هغوئ باندې زما دپاره د هغه ځائ نه لعنت ووائې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4114, 'Numbers 23:28', 'Numbers', 23, 28, '&nbsp;نو هغۀ بلعام د فعور غرۀ سر ته بوتلو چې صحرا ته مخامخ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4115, 'Numbers 23:29', 'Numbers', 23, 29, '&nbsp;بلعام هغۀ ته ووئيل، ”دلته زما دپاره اووۀ قربان‌ګاه جوړې کړه او اووۀ غوَيى او اووۀ ګډان ما له راوله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4116, 'Numbers 23:30', 'Numbers', 23, 30, '&nbsp;بلق هم هغه شان وکړل چې څنګه يې وئيلى وُو او يو غوَيے او يو ګډ يې په هره يوه قربان‌ګاه باندې پېش کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4117, 'Numbers 24:1', 'Numbers', 24, 1, '&nbsp;نو بلعام ته دا پته ولګېده چې د مالِک خُدائ رضا دا وه چې بنى اِسرائيلو له برکت ورکړى، نو هغه فال کتلو له لا نۀ ړو، لکه چې مخکښې تلے وو. هغه د صحرا په طرف روان شو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4118, 'Numbers 24:2', 'Numbers', 24, 2, '&nbsp;او اِسرائيليان يې وليدل چې قبيله په قبيله يې خېمې لګولې وې. نو د خُدائ پاک روح په هغۀ باندې راغلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4119, 'Numbers 24:3', 'Numbers', 24, 3, '&nbsp;او هغۀ دا پېغام ورکړو، ”د بلعام د بعور د زوئ دا دے پېغام، او د دې سړى خبرې رښتونى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4120, 'Numbers 24:4', 'Numbers', 24, 4, '&nbsp;د خُدائ پاک خبرې څوک اورى. په غړېدلو سترګو راباندې جذبه غالبه شوه د قادر خُدائ د طرف نه ما يوه رويا يعنې په وېښه خوب وليدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4121, 'Numbers 24:5', 'Numbers', 24, 5, '&nbsp;د بنى اِسرائيلو خېمې ښائسته دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4122, 'Numbers 24:6', 'Numbers', 24, 6, '&nbsp;د کجورو اوږدو قطارونو په شان يا د سيند د غاړې د باغونو په شان، د مالِک خُدائ کَرلى عُود په شان يا د اوبو په غاړه د دِيار په شان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4123, 'Numbers 24:7', 'Numbers', 24, 7, '&nbsp;دا به په اوبو مَړې شى او د هغوئ اولاد به لکه د زياتو اوبو په شان وى. د هغوئ بادشاه به د اجاج نه لوئ وى، او د هغۀ بادشاهى به اوچته وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4124, 'Numbers 24:8', 'Numbers', 24, 8, '&nbsp;خُدائ پاک هغوئ د مِصر نه راوويستل، په هغوئ کښې د ځنګلى غوَيى په شان طاقت شته، هغوئ خپل دشمنان تباه کوى، د هغوئ هډُوکى ماتوى او په غشو باندې يې وولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4125, 'Numbers 24:9', 'Numbers', 24, 9, '&nbsp;دا قوم د طاقتور ازمرى په شان دے، کله چې هغه ملاست وى، هيڅ څوک دا زړۀ نۀ شى کولے چې پايې‌څوى. څوک چې بنى اِسرائيلو دپاره برکت وغواړى نو هغوئ به په خپله برکتى شى، او څوک چې ورباندې لعنت ووائى نو هغوئ به په خپله لعنتى شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4126, 'Numbers 24:10', 'Numbers', 24, 10, '&nbsp;بلق د غصې نه غاښونه وچيچل او بلعام ته يې ووئيل، ”ما تۀ د دې دپاره راغوښتلے يې چې زما په دشمنانو باندې لعنت ووائې، خو ګوره، د لعنت په ځائ تا د هغوئ دپاره درې ځلې برکت غوښتلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4127, 'Numbers 24:11', 'Numbers', 24, 11, '&nbsp;نو ورک شه او خپل کور ته لاړ شه. زما خيال دا وو چې اِنعام به درکړم، خو مالِک خُدائ دا اِنعام ستا په قسمت کښې نۀ دے ليکلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4128, 'Numbers 24:12', 'Numbers', 24, 12, '&nbsp;بلعام ورته په جواب کښې ووئيل، ”کوم پېغام وړُونکى چې تا ما ته رالېږلى وُو ما هغوئ ته ووئيل چې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4129, 'Numbers 24:13', 'Numbers', 24, 13, '&nbsp;کۀ تۀ ما له ستا په محل کښې ټول سرۀ زر او سپين زر هم راکړې، نو زۀ د ځان نه څۀ ښۀ يا بد نۀ شم کولے، څۀ چې ما ته مالِک خُدائ فرمائى نو زۀ به صِرف هغه کوم، زۀ د مالِک خُدائ د حُکم نافرمانى نۀ شم کولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4130, 'Numbers 24:14', 'Numbers', 24, 14, '&nbsp;بلعام بلق ته ووئيل، ”اوس زۀ واپس خپلو خلقو له ځم، خو د تلو نه مخکښې زۀ تا له خبر درکوم چې په راتلونکى وخت کښې به اِسرائيليان ستا د خلقو سره څۀ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4131, 'Numbers 24:15', 'Numbers', 24, 15, '&nbsp;بيا هغۀ دا پېغام ورکړو، ”د بلعام د بعور د زوئ دا دے پېغام، او د دې سړى خبرې رښتونى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4132, 'Numbers 24:16', 'Numbers', 24, 16, '&nbsp;څوک چې د خُدائ پاک خبرې اورى او هغه حِکمت اخلى چې د خُدائ تعالىٰ نه راځى. په غړېدلو سترګو راباندې جذبه غالبه شوه د قادر خُدائ د طرف نه ما يوه رويا وليده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4133, 'Numbers 24:17', 'Numbers', 24, 17, '&nbsp;زۀ راتلونکے وخت وينم، زۀ د بنى اِسرائيلو قوم وينم. د روښانه ستورى په شان، په دې قوم کښې به يو بادشاه پېدا شى. دا ستورے به د بنى اِسرائيلو نه راشى. هغه به د موآب مشران هلاک کړى او هغه به د شيث ټول اولاد تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4134, 'Numbers 24:18', 'Numbers', 24, 18, '&nbsp;هغه به په ادوم کښې په خپلو دشمنانو بريالے شى او د هغوئ مُلک به قبضه کړى، او اِسرائيليان به مسلسل بريالى کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4135, 'Numbers 24:19', 'Numbers', 24, 19, '&nbsp;اِسرائيليان به هغوئ د پښو لاندې کړى او په ښار کښې چې څوک ژوندى پاتې وى نو هغه به تباه کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4136, 'Numbers 24:20', 'Numbers', 24, 20, '&nbsp;بيا بلعام په خپله رويا کښې عماليقيان وليدل او دا پېغام يې ورکړو، ”عماليقيان د ټولو نه زيات تکړه قوم دے، خو په آخر کښې به د همېشه دپاره ورک شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4137, 'Numbers 24:21', 'Numbers', 24, 21, '&nbsp;هغۀ په خپل خيال کښې قينيان وليدل او دا پېغام يې ورکړو، ”ستاسو د اوسېدو ځائ ډېر پوخ دے، داسې پوخ لکه چې د يو کور بنياد چې په کاڼو اېښودے شوے وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4138, 'Numbers 24:22', 'Numbers', 24, 22, '&nbsp;خو تاسو قينيان به تباه شئ کله چې اسوريان تاسو قېديان بوځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4139, 'Numbers 24:23', 'Numbers', 24, 23, '&nbsp;بلعام دا پېغام ورکړو، ”هغه څوک بچ کولے شى چې خُدائ پاک يې تباه کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4140, 'Numbers 24:24', 'Numbers', 24, 24, '&nbsp;سمندرى جهازُونه به د قبرص نه راشى، هغوئ به اسور او عِبر فتح کړى، خو په آخر کښې به قبرص هم تباه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4141, 'Numbers 24:25', 'Numbers', 24, 25, '&nbsp;بيا بلعام روان شو او واپس کور ته لاړو او بلق هم په خپله مخه لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4142, 'Numbers 25:1', 'Numbers', 25, 1, '&nbsp;کله چې اِسرائيليان د کيکرو په وادۍ کښې دېره وُو، نو د موآبيانو ښځو سره يې زنا شروع کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4143, 'Numbers 25:2', 'Numbers', 25, 2, '&nbsp;ښځو هغوئ ته ووئيل چې د هغوئ معبودانو ته قربانۍ وکړى، نو خلقو هغه قربانۍ وخوړلې او د هغوئ د معبود عبادت يې وکړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4144, 'Numbers 25:3', 'Numbers', 25, 3, '&nbsp;چې د فعور بعل وو. نو مالِک خُدائ بنى اِسرائيلو ته په قهر شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4145, 'Numbers 25:4', 'Numbers', 25, 4, '&nbsp;او موسىٰ ته يې وفرمائيل، ”د بنى اِسرائيلو ټول مشران بوځه او د خلقو په وړاندې يې پهانسى کړه، نو بيا به زما سخته غصه د بنى اِسرائيلو نه سړه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4146, 'Numbers 25:5', 'Numbers', 25, 5, '&nbsp;موسىٰ د بنى اِسرائيلو قاضيانو ته وفرمائيل، ”ستاسو هر يو کس به د خپلې قبيلې نه هر هغه سړے وژنئ څوک چې د فعور د بعل عبادت کوونکے جوړ شوے وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4147, 'Numbers 25:6', 'Numbers', 25, 6, '&nbsp;بيا يو اِسرائيلى يوه ميديانې ښځه د موسىٰ او د ټول قوم په مخکښې خپلې خېمې ته دننه بوتله، په هغه وخت کله چې هغوئ د مالِک خُدائ د حضور خېمې په دروازه کښې ماتم کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4148, 'Numbers 25:7', 'Numbers', 25, 7, '&nbsp;نو چې فينحاس، د اِلى‌عزر زوئ او د هارون نمسى دا وليدل، هغه د قبيلې نه پاڅېدو او لاړو. هغۀ نېزه راواخستله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4149, 'Numbers 25:8', 'Numbers', 25, 8, '&nbsp;او په هغه سړى او ښځې پسې خېمې ته ورننوتلو او نېزه يې د هغه سړى او ښځې د خېټې نه بل خوا وويستله. نو داسې هغه وبا بس شوه کومې چې اِسرائيليان تباه کول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4150, 'Numbers 25:9', 'Numbers', 25, 9, '&nbsp;خو وبا څليريشت زره کسان وژلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4151, 'Numbers 25:10', 'Numbers', 25, 10, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4152, 'Numbers 25:11', 'Numbers', 25, 11, '&nbsp;”فينحاس زوئ د اِلى‌عزر چې د هارون اِمام زوئ دے هغۀ زما غصه د بنى اِسرائيلو دپاره ختمه کړه چې هغوئ کښې هغۀ غېرت وکړو، نو ما د خپل غېرت په وجه بنى اِسرائيل هلاک نۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4153, 'Numbers 25:12', 'Numbers', 25, 12, '&nbsp;نو ورته ووايه چې زۀ د هغۀ سره د امن لوظ کوم چې د راتلونکى ټولو وختونو دپاره به وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4154, 'Numbers 25:13', 'Numbers', 25, 13, '&nbsp;هغه او د هغۀ اولاد به د همېشه دپاره اِمامان مقررولے شى، ځکه چې هغۀ په ما باندې غېرت وکړو او د بنى اِسرائيلو د ګناه کفاره يې ادا کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4155, 'Numbers 25:14', 'Numbers', 25, 14, '&nbsp;کوم سړے چې د ميديانې ښځې سره وژلے شوے وو د هغۀ نوم زِمرى وو، هغه د سلو زوئ وو، چې د شمعون په قبيلې کښې د يو خاندان مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4156, 'Numbers 25:15', 'Numbers', 25, 15, '&nbsp;د هغه ښځې نوم کزبى وو. د هغې پلار صور، د ميديانې قبيلو د يوې قبيلې مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4157, 'Numbers 25:16', 'Numbers', 25, 16, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4158, 'Numbers 25:17', 'Numbers', 25, 17, '&nbsp;”په ميديانيانو حمله وکړه او هغوئ تباه کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4159, 'Numbers 25:18', 'Numbers', 25, 18, '&nbsp;د هغه بد عمل په وجه، چې په فعور کښې يې په دوکه په تاسو باندې عبادت وکړو او د کزبى په وجه، چې هغه د وبا په وخت په فعور کښې وژلے شوې وه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4160, 'Numbers 26:1', 'Numbers', 26, 1, '&nbsp;د وبا نه پس مالِک خُدائ موسىٰ او د هارون زوئ اِلى‌عزر ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4161, 'Numbers 26:2', 'Numbers', 26, 2, '&nbsp;”د بنى اِسرائيلو د ټول قوم د کورَنو په مطابق مردم‌شمارى وکړئ، د هغو ټولو سړو چې عُمر يې شل کاله يا د دې نه زيات وى او چې جنګ کولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4162, 'Numbers 26:5', 'Numbers', 26, 5, '&nbsp;د يعقوب د مشر زوئ روبين په قبيله کښې دا قبيلې وې، حنوک، فلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4163, 'Numbers 26:6', 'Numbers', 26, 6, '&nbsp;حصرون او کرمى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4164, 'Numbers 26:7', 'Numbers', 26, 7, '&nbsp;دوئ په شمېر کښې درې څلوېښت زره اووۀ سوه او دېرش سړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
